module UW_Distance_Optimizer (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] gravity_in [0:7],\n    input [7:0] connections_in [0:7],\n    input [7:0] human_mask,\n    input [7:0] alien_mask,\n    output reg [15:0] min_distance,\n    output reg done\n);\n\n// State declarations\nlocalparam [3:0] IDLE            = 4'd0;\nlocalparam [3:0] READ_GRAPH      = 4'd1;\nlocalparam [3:0] FIND_PATHS      = 4'd2;\nlocalparam [3:0] CALCULATE_DIST  = 4'd3;\nlocalparam [3:0] APPLY_DEVICE    = 4'd4;\nlocalparam [3:0] UPDATE_MIN      = 4'd5;\nlocalparam [3:0] COMPLETE        = 4'd6;\n\nreg [3:0] state;\nreg [3:0] next_state;\nreg [7:0] cycle_counter;\nlocalparam [7:0] MAX_CYCLES = 8'd100;\n\n// Internal registers\nreg [2:0] device_node;\nreg [15:0] best_distance;\nreg [15:0] current_distance;\n\n// Graph storage\nreg [7:0] modified_gravity [0:7];\nreg [63:0] adjacency_matrix;\n\n// Temporary calculation registers\nreg signed [15:0] cap_val;\nreg signed [15:0] pot_val;\nreg signed [15:0] ind_val;\n\ninteger i;  // For loop index\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        done <= 1'b0;\n        min_distance <= 16'hFFFF;\n        best_distance <= 16'hFFFF;\n        device_node <= 3'd0;\n        cycle_counter <= 8'd0;\n        current_distance <= 16'd0;\n        \n        for (i = 0; i < 8; i = i + 1) begin\n            modified_gravity[i] <= 8'd0;\n        end\n    end else begin\n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                cycle_counter <= 8'd0;\n                if (start) begin\n                    state <= READ_GRAPH;\n                    best_distance <= 16'hFFFF;\n                    device_node <= 3'd0;\n                end\n            end\n\n            READ_GRAPH: begin\n                // Store gravity values\n                for (i = 0; i < 8; i = i + 1) begin\n                    modified_gravity[i] <= gravity_in[i];\n                end\n                state <= APPLY_DEVICE;\n            end\n\n            APPLY_DEVICE: begin\n                // Apply gravity dispersal device effect\n                modified_gravity[device_node] <= gravity_in[device_node] - 8'd1;\n                if (device_node > 0)\n                    modified_gravity[device_node-1] <= gravity_in[device_node-1] + 8'd1;\n                if (device_node < 7)\n                    modified_gravity[device_node+1] <= gravity_in[device_node+1] + 8'd1;\n                state <= CALCULATE_DIST;\n            end\n\n            CALCULATE_DIST: begin\n                // Simplified distance calculation example\n                cap_val <= (modified_gravity[0] + modified_gravity[1]);\n                pot_val <= (modified_gravity[0] - modified_gravity[1]);\n                ind_val <= (modified_gravity[0] * modified_gravity[1]);\n                current_distance <= pot_val * (cap_val * cap_val - ind_val);\n                state <= UPDATE_MIN;\n            end\n\n            UPDATE_MIN: begin\n                if (current_distance < best_distance)\n                    best_distance <= current_distance;\n\n                if (device_node < 3'd7) begin\n                    device_node <= device_node + 3'd1;\n                    state <= APPLY_DEVICE;\n                    // Restore original gravity values\n                    for (i = 0; i < 8; i = i + 1) begin\n                        modified_gravity[i] <= gravity_in[i];\n                    end\n                end else begin\n                    state <= COMPLETE;\n                end\n            end\n\n            COMPLETE: begin\n                min_distance <= best_distance;\n                done <= 1'b1;\n                state <= IDLE;\n            end\n\n            default: state <= IDLE;\n        endcase\n\n        // Safety timeout\n        cycle_counter <= cycle_counter + 8'd1;\n        if (cycle_counter >= MAX_CYCLES) begin\n            state <= IDLE;\n            done <= 1'b1;\n        end\n    end\nend\n\nendmodule